  ShowSoftwareDialog=popup=>{popups.Add(popup);popup.WindowStartupLocation=WindowStartupLocation.Manual;popup.Left=popup.Top=-12000;popup.ShowActivated=false;UiMotion.SetEnabled(popup,false);popup.Show();};SoftwareCheck=token=>offer();
  try{
   await CheckSoftwareUpdatesAsync(false);check(Get<FrameworkElement>("RuleCenterBadge").Visibility==Visibility.Visible&&Get<Border>("ToastFrame").IsHitTestVisible&&Get<TextBlock>("ToastCountdown").Text.Contains("秒后自动关闭")&&Get<TextBlock>("ToastText").Text.Contains("点击下载更新")&&popups.Count==0,"Startup checks show the clickable download hint, countdown and red badge without opening a window automatically");
   Get<Border>("ToastFrame").RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,Environment.TickCount,MouseButton.Left){RoutedEvent=UIElement.MouseLeftButtonUpEvent});check(softwareDialog!=null&&pages.Count==0,"The homepage update notification opens a small window without navigating away");softwareDialog.Window.Close();
   OpenSettings(new CleanerSettings(),null,s=>{});var settingsRoot=settingsView.Root;check(((FrameworkElement)settingsRoot.FindName("AboutBadge")).Visibility==Visibility.Visible&&((Button)settingsRoot.FindName("OpenHistory"))!=null,"Settings exposes cleanup history and the About update badge");
   ((TabControl)settingsRoot.FindName("RulesTabs")).SelectedItem=settingsRoot.FindName("ApplicationsTab");await Task.Delay(60);UiMotion.SetEnabled(Window,true);var expander=(Expander)settingsRoot.FindName("PortableExpander");expander.IsExpanded=true;await Task.Delay(100);var body=(FrameworkElement)expander.Template.FindName("ExpandBody",expander);check(body.ActualHeight>0,"Portable directory expansion reveals content during its height animation");await Task.Delay(180);expander.IsExpanded=false;await Task.Delay(280);check(body.ActualHeight==0,"Portable directory collapse settles without an empty gap");UiMotion.SetEnabled(Window,false);
   ((TabControl)settingsRoot.FindName("RulesTabs")).SelectedItem=settingsRoot.FindName("RulesTab");((Button)settingsRoot.FindName("Save")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(((SolidColorBrush)Get<Border>("ToastFrame").BorderBrush).Color==Color.FromRgb(86,201,139),"Saving rule settings uses the green success notification");try{RuleCenter.UpdateFixture=(ini,url,token)=>Task.FromResult(0);((Button)settingsRoot.FindName("Check")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Get<TextBlock>("ToastText").Text=="当前规则已就绪，重新扫描后生效。"&&((SolidColorBrush)Get<Border>("ToastFrame").BorderBrush).Color==Color.FromRgb(86,201,139),"A successful rule update uses the green ready notification");}finally{RuleCenter.UpdateFixture=null;}App.Render(Window,Path.Combine(output,"rules-ready-success.png"));((Button)settingsRoot.FindName("JsonGuide")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(((TextBox)pages.Last().FindName("DocumentText")).Text.Contains("\"Schema\": 1"),"Rule management opens the embedded JSON authoring guide");BackPage();OpenAbout();var about=pages.Last();check(((TextBlock)about.FindName("AboutBuild")).Text.Contains(ReleaseVersion.Build.ToString())&&((FrameworkElement)about.FindName("AboutUpdateBadge")).Visibility==Visibility.Visible,"About displays the internal build number and update badge");
   ((Button)about.FindName("ReleaseNotesButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var notes=popups.Last();check(((Button)about.FindName("ReleaseNotesButton")).Content.ToString()=="本版更新内容"&&about.FindName("ReleaseSummary")==null&&((TextBlock)notes.FindName("ReleaseSummary")).Text==ReleaseHighlights.Current,"Version highlights use a small correctly named button and display the configured release summary");var chrome=System.Windows.Shell.WindowChrome.GetWindowChrome(notes);check(chrome!=null&&chrome.GlassFrameThickness==new Thickness(0)&&((SolidColorBrush)((Grid)notes.FindName("DialogCaption")).Background).Color==Color.FromRgb(29,42,52),"Release notes use the dark custom caption without a native white glass strip");App.Render(notes,Path.Combine(output,"release-highlights.png"));notes.Close();
   var card=(Border)about.FindName("SoftwareUpdateCard");var title=(TextBlock)about.FindName("SoftwareUpdateTitle");var checkButton=(Button)about.FindName("SoftwareUpdateButton");var icon=(TextBlock)about.FindName("UpdateCheckIcon");Window.UpdateLayout();var notesButton=(Button)about.FindName("ReleaseNotesButton");check(notesButton.ActualWidth==checkButton.ActualWidth&&notesButton.ActualHeight==checkButton.ActualHeight&&notesButton.FontSize==checkButton.FontSize&&notesButton.Padding==checkButton.Padding,"Release notes and update check actions have matching dimensions and typography");double cardCenter=card.ActualHeight/2;check(Math.Abs(title.TranslatePoint(new Point(0,title.ActualHeight/2),card).Y-cardCenter)<2&&Math.Abs(checkButton.TranslatePoint(new Point(0,checkButton.ActualHeight/2),card).Y-cardCenter)<2&&Math.Abs(icon.TranslatePoint(new Point(0,icon.ActualHeight/2),checkButton).Y-checkButton.ActualHeight/2)<2,"Update title, action and refresh glyph are vertically centered within the card");check(about.FindName("AboutLogo")is BrandMark&&((BrandMark)about.FindName("AboutLogo")).OutlineProgress==1,"About uses the complete scale-independent application icon");
   using(var gate=new ManualResetEventSlim(false)){
    SoftwareCheck=token=>{gate.Wait(token);return new SoftwareRelease{Version=ReleaseVersion.Display,Build=ReleaseVersion.Build};};var button=(Button)about.FindName("SoftwareUpdateButton");UiMotion.SetEnabled(Window,true);var checking=CheckSoftwareUpdatesAsync(true);
    var loading=(ProgressBar)about.FindName("AboutUpdateProgress");Window.UpdateLayout();check(loading.Visibility==Visibility.Visible&&loading.IsIndeterminate&&InsideControl(loading,card)&&Math.Abs(loading.TranslatePoint(new Point(0,loading.ActualHeight),card).Y-card.ActualHeight)<2&&!button.IsEnabled&&pages.Last()==about&&Application.Current.Windows.Count==windows,"Checking integrates its scrolling loading bar into the bottom edge of the update card");var band=(FrameworkElement)loading.Template.FindName("LoadingBand",loading);await Task.Delay(100);double first=((TranslateTransform)band.RenderTransform).X;await Task.Delay(220);double next=((TranslateTransform)band.RenderTransform).X;check(next>first&&((TranslateTransform)band.RenderTransform).HasAnimatedProperties,"The integrated loading highlight visibly travels while a check is pending; positions="+first+"/"+next);App.Render(Window,Path.Combine(output,"update-checking.png"));gate.Set();await checking;UiMotion.SetEnabled(Window,false);
    check(((ProgressBar)about.FindName("AboutUpdateProgress")).Visibility==Visibility.Collapsed&&button.IsEnabled&&Get<TextBlock>("ToastText").Text.Contains("最新版本")&&Application.Current.Windows.Count==windows,"No-update checks stop loading and show only the top notification");
   }
   SoftwareCheck=token=>{throw new IOException("Fixture connection failure");};await CheckSoftwareUpdatesAsync(true);check(Get<TextBlock>("ToastText").Text.Contains("检查失败")&&Application.Current.Windows.Count==windows&&pages.Last()==about,"Failed checks show a top notification and preserve the About page");
   SoftwareCheck=token=>offer();await CheckSoftwareUpdatesAsync(true);var dialog=softwareDialog;check(dialog!=null&&dialog.Window.Width<Window.Width&&pages.Last()==about&&dialog.Install.IsEnabled,"A manual check with an update opens a small download window while About stays in place");App.Render(dialog.Window,Path.Combine(output,"software-update.png"));
   UiText.SetLanguage("en");check(((TextBlock)dialog.Window.FindName("SoftwareNotes")).Text==ReleaseHighlights.English&&((Button)about.FindName("ReleaseNotesButton")).Content.ToString()=="What's new in this version","The summary dialog and About controls follow the English interface");App.Render(dialog.Window,Path.Combine(output,"software-update-english.png"));
   var entered=new TaskCompletionSource<bool>();SoftwareSession=()=>Path.Combine(output,"fixture-update-session");SoftwareDownload=(asset,directory,token,progress)=>{progress(asset.Size/2,asset.Size);entered.TrySetResult(true);token.WaitHandle.WaitOne();token.ThrowIfCancellationRequested();throw new IOException("Fixture download must be cancelled");};dialog.Install.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var downloading=LastSoftwareOperation;await entered.Task;await Task.Delay(60);
   check(dialog.Progress.Visibility==Visibility.Visible&&dialog.Progress.Value==50&&dialog.ProgressText.Text.StartsWith("50%")&&dialog.ProgressText.Text.Contains("512.0 KB / 1.0 MB")&&dialog.Cancel.Visibility==Visibility.Visible&&!dialog.Install.IsEnabled,"The download window shows real byte progress, percentage and total size while preventing duplicate downloads");App.Render(dialog.Window,Path.Combine(output,"software-download.png"));dialog.Cancel.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await downloading;check(!installingSoftware&&dialog.Install.IsEnabled&&dialog.State.Text.Contains("cancelled")&&dialog.Window.IsVisible,"Cancelling download leaves the current app and update dialog available for retry");dialog.Later.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
  }finally{if(softwareDownloadStop!=null)softwareDownloadStop.Cancel();foreach(var popup in popups)if(popup.IsVisible)popup.Close();SoftwareCheck=loader;SoftwareDownload=downloader;SoftwareSession=sessions;ShowSoftwareDialog=show;softwareRelease=previous;RefreshSoftwareUpdateState();while(pages.Count>0)BackPage();UiText.SetLanguage("zh-CN");UiMotion.SetEnabled(Window,false);}
 }
